package com.johnny.hotel.cashier;import com.johnny.hotel.cashier.CashierModels.*;import com.johnny.hotel.businessdate.BusinessDateService;import com.johnny.hotel.entity.SysAuditLog;import com.johnny.hotel.exception.BusinessException;import com.johnny.hotel.mapper.SysAuditLogMapper;import com.johnny.hotel.pagination.*;import com.johnny.hotel.payment.*;import com.johnny.hotel.task.*;import lombok.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.math.*;import java.time.*;import java.util.*;
@Service@RequiredArgsConstructor public class CashierService{private final CashierMapper db;private final CashierAccess access;private final BusinessDateService dates;private final CashierPostingService posting;private final HotelTaskMapper tasks;private final TaskRecordMapper records;private final HotelTaskService taskService;private final PaymentCoreMapper transactions;private final SysAuditLogMapper audits;private final PaginationSupport pages;private final Clock clock;
 private void req(boolean b,String m){if(!b)throw new BusinessException(m);}private void one(int n){if(n!=1)throw new BusinessException(409,"Cashier state changed");}private BigDecimal money(BigDecimal x){req(x!=null&&x.signum()>=0&&x.scale()<=2,"Invalid cash amount");return x.setScale(2);}private LocalDateTime now(){return LocalDateTime.now(clock);}
 @Transactional public Drawer createDrawer(CreateDrawer r){var a=access.actor();access.finance(a);var d=Drawer.builder().code(r.code().trim()).name(r.name().trim()).currency(r.currency()).createdBy(a.id()).build();one(db.insertDrawer(d));audit(a.id(),"CREATE_CASH_DRAWER",d.getId());return db.drawer(d.getId());}
 @Transactional public ShiftView open(Long drawerId,Count c){var a=access.actor();access.staff(a);var d=db.lockDrawer(drawerId);req(d!=null&&"ACTIVE".equals(d.getStatus()),"Cash drawer unavailable");req(d.getActiveShiftId()==null,"Cash drawer already has an active shift");BigDecimal count=money(c.amount());var s=Shift.builder().drawerId(drawerId).operatorUserId(a.id()).openingCount(count).openedAt(now()).openingBusinessDate(dates.postingDate()).build();one(db.insertShift(s));one(db.activate(drawerId,s.getId()));var previous=db.previous(drawerId);if(previous!=null){var h=Handover.builder().drawerId(drawerId).previousShiftId(previous.getId()).nextShiftId(s.getId()).previousClosingCount(previous.getClosingCount()).nextOpeningCount(count).differenceAmount(count.subtract(previous.getClosingCount())).recordedBy(a.id()).build();one(db.insertHandover(h));}audit(a.id(),"OPEN_CASHIER_SHIFT",s.getId());return view(s.getId());}
 @Transactional public ShiftView countClose(Long id,Count c){var a=access.actor();var s=db.lockShift(id);req(s!=null&&s.getOperatorUserId().equals(a.id())&&Set.of("ACTIVE","CLOSING").contains(s.getStatus()),"Cashier shift cannot be counted");one(db.countClose(id,money(c.amount())));return view(id);}
 @Transactional public ShiftView close(Long id,Count c){var a=access.actor();var s=db.lockShift(id);req(s!=null&&s.getOperatorUserId().equals(a.id())&&"CLOSING".equals(s.getStatus()),"Cashier shift is not ready to close");BigDecimal expected=db.expected(id),counted=s.getClosingCount(),diff=counted.subtract(expected);if(diff.signum()!=0&&db.variance(id)==null){req(c.reason()!=null&&!c.reason().isBlank(),"Cash variance reason is required");var v=Variance.builder().shiftId(id).expectedAmount(expected).countedAmount(counted).differenceAmount(diff).varianceType(diff.signum()>0?"OVER":"SHORT").reason(c.reason().trim()).recordedBy(a.id()).build();one(db.insertVariance(v));}one(db.close(id,expected,counted,diff,dates.postingDate(),now()));one(db.deactivate(s.getDrawerId(),id));audit(a.id(),"CLOSE_CASHIER_SHIFT",id);return view(id);}
 @Transactional public Transfer requestTransfer(Long shiftId,TransferRequest r){var a=access.actor();access.staff(a);var old=db.transferByKey(r.requestKey());if(old!=null)return old;var s=db.lockShift(shiftId);req(s!=null&&s.getOperatorUserId().equals(a.id())&&"ACTIVE".equals(s.getStatus()),"Active owned shift required");String type=r.type().trim().toUpperCase();req(Set.of("CASH_DROP","FINANCE_REPLENISHMENT","CASH_OUT").contains(type),"Unsupported cash transfer request");var t=HotelTask.builder().taskType(TaskType.GENERAL.getCode()).targetRole("FINANCE").status(TaskStatus.PENDING.getCode()).assignmentMode(0).executionType(0).title(type.replace('_',' ')).description(r.note()).sourceKey("CASH_TRANSFER:"+r.requestKey()).requestKey(r.requestKey()).createdBy(a.id()).build();one(tasks.insert(t));one(records.insert(TaskRecord.builder().taskId(t.getId()).recordType(TaskRecordType.TASK_CREATED.getCode()).actorUserId(a.id()).detail("Finance cash handover requested").build()));var d=db.drawer(s.getDrawerId());var x=Transfer.builder().drawerId(d.getId()).shiftId(shiftId).taskId(t.getId()).requestType(type).amount(money(r.amount())).currency(d.getCurrency()).requestKey(r.requestKey()).requestedBy(a.id()).note(r.note()).build();one(db.insertTransfer(x));audit(a.id(),"REQUEST_"+type,x.getId());return x;}
 @Transactional public Transfer confirmTransfer(Long id){var a=access.actor();access.finance(a);var x=db.lockTransfer(id);req(x!=null,"Cash transfer request not found");if("COMPLETED".equals(x.getStatus()))return x;req("PENDING".equals(x.getStatus()),"Cash transfer request is not pending");taskService.completeCashTransfer(x.getTaskId(),"Finance confirmed physical cash handover");String dir="FINANCE_REPLENISHMENT".equals(x.getRequestType())?"IN":"OUT";posting.post(x.getRequestedBy(),dir,x.getRequestType(),x.getAmount(),x.getCurrency(),"CASH_TRANSFER",x.getId(),"cash-transfer-"+x.getId(),x.getNote());one(db.completeTransfer(id,a.id(),now()));one(transactions.insertTransaction(HotelTransactionRecord.builder().direction("INTERNAL_TRANSFER").amount(x.getAmount()).currency(x.getCurrency()).sourceType(x.getRequestType()).sourceId(x.getId()).businessReferenceType("CASH_DRAWER").businessReferenceId(x.getDrawerId()).paymentMethod("CASH").channel("CASHIER").initiatorType("HOTEL").operatorUserId(a.id()).description("Physical cash handover").occurredAt(now()).businessDate(dates.postingDate()).build()));audit(a.id(),"CONFIRM_"+x.getRequestType(),id);return db.lockTransfer(id);}
 @Transactional public Transfer cancelTransfer(Long id){var a=access.actor();var x=db.lockTransfer(id);req(x!=null,"Cash transfer request not found");req(a.id().equals(x.getRequestedBy())||a.roles().stream().anyMatch(Set.of("MANAGER","FINANCE","OWNER","SUPER_ADMIN")::contains),"Cash transfer cancellation denied");if("CANCELLED".equals(x.getStatus()))return x;taskService.cancelCashTransfer(x.getTaskId(),"Cash transfer request cancelled");one(db.cancelTransfer(id));return db.lockTransfer(id);}
 @Transactional public Variance reviewVariance(Long id,String note){var a=access.actor();req(a.roles().stream().anyMatch(Set.of("MANAGER","OWNER","SUPER_ADMIN")::contains),"Variance review denied");var v=db.lockVariance(id);req(v!=null,"Cash variance not found");if("REVIEWED".equals(v.getStatus()))return v;one(db.reviewVariance(id,a.id(),now(),note));audit(a.id(),"REVIEW_CASH_VARIANCE",id);return db.lockVariance(id);}
 @Transactional(readOnly=true)public ShiftView get(Long id){var a=access.actor();var s=db.shift(id);req(s!=null,"Cashier shift not found");if(!a.id().equals(s.getOperatorUserId()))access.oversight(a);return view(id);}@Transactional(readOnly=true)public PageResult<Shift> history(Integer page,Integer size){var a=access.actor();access.oversight(a);var w=pages.window(page,size,true);return pages.result(w,db.shifts(w.offset(),pages.limit(w)),db.shiftCount());}
 private ShiftView view(Long id){var s=db.shift(id);return new ShiftView(s,db.expected(id),db.variance(id),db.handover(id));}private void audit(Long actor,String action,Long id){one(audits.insert(SysAuditLog.builder().operatorId(actor).action(action).detail("Cashier "+id).build()));}
}
